import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class FindDeclarationsAndSetters_visit_TriageGen1Test {

    private FindDeclarationsAndSetters finder;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Node nameNode;

    @Mock
    private JsName jsName;

    @Mock
    private NameInformation nameInformation;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // We spy on the class under test to mock the internal protected/private methods 
        // like createNameInformation, recordSet, recordPrototypeSet, getName, etc.
        finder = spy(new FindDeclarationsAndSetters());
    }

    @Test
    public void testVisit_GlobalVarDeclaration() {
        when(t.inGlobalScope()).thenReturn(true);
        when(NodeUtil.isVarDeclaration(n)).thenReturn(true);
        when(finder.createNameInformation(t, n, parent)).thenReturn(nameInformation);
        when(nameInformation.name).thenReturn("varName");

        finder.visit(t, n, parent);

        verify(finder).recordSet("varName", n);
    }

    @Test(expected = NullPointerException.class)
    public void testVisit_GlobalVarDeclaration_NullNameInfo() {
        when(t.inGlobalScope()).thenReturn(true);
        when(NodeUtil.isVarDeclaration(n)).thenReturn(true);
        // This triggers Preconditions.checkNotNull(ns)
        when(finder.createNameInformation(t, n, parent)).thenReturn(null);

        finder.visit(t, n, parent);
    }

    @Test
    public void testVisit_GlobalFunctionDeclaration() {
        when(t.inGlobalScope()).thenReturn(true);
        when(NodeUtil.isFunctionDeclaration(n)).thenReturn(true);
        when(n.getFirstChild()).thenReturn(nameNode);
        when(finder.createNameInformation(t, nameNode, n)).thenReturn(nameInformation);
        when(nameNode.getString()).thenReturn("funcName");
        when(finder.getName("funcName", true)).thenReturn(jsName);
        when(jsName.name).thenReturn("jsFuncName");

        finder.visit(t, n, parent);

        verify(finder).recordSet("jsFuncName", nameNode);
    }

    @Test
    public void testVisit_GlobalFunctionDeclaration_NullNameInfo() {
        when(t.inGlobalScope()).thenReturn(true);
        when(NodeUtil.isFunctionDeclaration(n)).thenReturn(true);
        when(n.getFirstChild()).thenReturn(nameNode);
        when(finder.createNameInformation(t, nameNode, n)).thenReturn(null);

        finder.visit(t, n, parent);

        verify(finder, never()).getName(any(String.class), anyBoolean());
    }

    @Test
    public void testVisit_GlobalObjectLitKey() {
        when(t.inGlobalScope()).thenReturn(true);
        when(NodeUtil.isVarDeclaration(n)).thenReturn(false);
        when(NodeUtil.isFunctionDeclaration(n)).thenReturn(false);
        when(NodeUtil.isObjectLitKey(n, parent)).thenReturn(true);
        when(finder.createNameInformation(t, n, parent)).thenReturn(nameInformation);
        when(nameInformation.name).thenReturn("keyName");

        finder.visit(t, n, parent);

        verify(finder).recordSet("keyName", n);
    }

    @Test
    public void testVisit_GlobalObjectLitKey_NullNameInfo() {
        when(t.inGlobalScope()).thenReturn(true);
        when(NodeUtil.isVarDeclaration(n)).thenReturn(false);
        when(NodeUtil.isFunctionDeclaration(n)).thenReturn(false);
        when(NodeUtil.isObjectLitKey(n, parent)).thenReturn(true);
        when(finder.createNameInformation(t, n, parent)).thenReturn(null);

        finder.visit(t, n, parent);

        verify(finder, never()).recordSet(any(String.class), any(Node.class));
    }

    @Test
    public void testVisit_Assignment_NotPrototype() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isAssign()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(nameNode);
        when(finder.createNameInformation(t, nameNode, n)).thenReturn(nameInformation);
        when(nameInformation.isPrototype).thenReturn(false);
        when(nameInformation.name).thenReturn("assignName");

        finder.visit(t, n, parent);

        verify(finder).recordSet("assignName", nameNode);
        verify(finder, never()).recordPrototypeSet(any(), any(), any());
    }

    @Test
    public void testVisit_Assignment_Prototype() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isAssign()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(nameNode);
        when(finder.createNameInformation(t, nameNode, n)).thenReturn(nameInformation);
        when(nameInformation.isPrototype).thenReturn(true);
        when(nameInformation.prototypeClass).thenReturn("Class");
        when(nameInformation.prototypeProperty).thenReturn("prop");

        finder.visit(t, n, parent);

        verify(finder).recordPrototypeSet("Class", "prop", n);
    }

    @Test
    public void testVisit_Call_AffectsClassDef() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isAssign()).thenReturn(false);
        when(n.isCall()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(nameNode);
        when(finder.createNameInformation(t, nameNode, n)).thenReturn(nameInformation);
        when(nameInformation.onlyAffectsClassDef).thenReturn(true);
        when(nameInformation.name).thenReturn("classConstructor");
        when(finder.getName("classConstructor", false)).thenReturn(jsName);
        when(jsName.name).thenReturn("jsClassName");

        // Mocking parent structure for ClassDefiningFunctionNode constructor
        Node grandParent = mock(Node.class);
        when(parent.getParent()).thenReturn(grandParent);

        finder.visit(t, n, parent);

        // Verify that refNodes.add is implicitly called via the logic (requires refNodes to be accessible or side-effect observable)
        // Since refNodes is likely an internal list, we check if the logic reaches that point.
        // In a real scenario, we'd verify the state of the finder object.
    }

    @Test
    public void testVisit_Call_DoesNotAffectClassDef() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isAssign()).thenReturn(false);
        when(n.isCall()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(nameNode);
        when(finder.createNameInformation(t, nameNode, n)).thenReturn(nameInformation);
        when(nameInformation.onlyAffectsClassDef).thenReturn(false);

        finder.visit(t, n, parent);

        verify(finder, never()).getName(any(String.class), eq(false));
    }

    @Test
    public void testVisit_Call_NullJsName() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isAssign()).thenReturn(false);
        when(n.isCall()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(nameNode);
        when(finder.createNameInformation(t, nameNode, n)).thenReturn(nameInformation);
        when(nameInformation.onlyAffectsClassDef).thenReturn(true);
        when(nameInformation.name).thenReturn("someName");
        when(finder.getName("someName", false)).thenReturn(null);

        finder.visit(t, n, parent);

        // Should not crash and should not add to refNodes
    }
}
